0b9\u4e2d\u7684\u6587\u4ef6\u8def\u5f84\u4e0e\u53c2\u6570\u662f\u57fa\u4e8e\u5bf9\u516c\u5f00 JaxMARL\uff08FLAIR/Instadeep \u7248\u672c\uff09\u4ee3\u7801\u5e93\u7684\u65e2\u6709\u4e86\u89e3\u7ed9\u51fa\u7684\uff0c**\u5728\u672c\u73af\u5883\u4e2d\u672a\u80fd\u9010\u4e00\u6838\u5b9e**\uff0c\u5df2\u5728\u5047\u8bbe\u4e0e\u4e0d\u786e\u5b9a\u6027\u4e2d\u660e\u786e\u6807\u6ce8\u3002\u82e5\u540e\u7eed\u80fd\u63d0\u4f9b\u4ed3\u5e93\uff0c\u7b2c\u4e00\u9879\u5de5\u4f5c\u5c31\u662f\u9010\u6761\u6838\u9a8c\u8fd9\u4e9b\u8def\u5f84\u4e0e\u9ed8\u8ba4\u8d85\u53c2\u6570\u3002\n\n### (1)(2) JaxMARL \u4e2d\u4e0e SMAX / PPO / Q-Learning \u76f8\u5173\u7684\u7ed3\u6784\uff08\u57fa\u4e8e\u65e2\u6709\u4e86\u89e3\uff0c\u5f85\u6838\u5b9e\uff09\n\n**SMAX \u73af\u5883\u5b9e\u73b0**\n- `jaxmarl/environments/smax/smax.py`\uff1aSMAX \u73af\u5883\uff08SMAC \u7684 JAX \u52a0\u901f\u91cd\u5b9e\u73b0\uff09\uff0c\u6838\u5fc3\u7c7b `SMAX`\uff08\u53ca\u5e26\u4e2d\u592e macro-controller \u7684 `SMAXMAC` \u53d8\u4f53\uff09\uff0c\u72b6\u6001\u4e3a\u7eaf JAX `JAXState`\uff0c`step_env`/`reset`/`observation` \u7b49\u5168\u90e8 jit \u53ef\u7f16\u8bd1\u3002\n- `jaxmarl/environments/smax/map_util.py`\uff1a\u5730\u56fe\u5b9a\u4e49\uff08\u5404 SMAC \u5730\u56fe\u7684\u5355\u4f4d\u6784\u6210\u3001\u8840\u91cf/\u653b\u51fb\u6570\u503c\uff09\uff0c\u5185\u7f6e\u5730\u56fe\u540d\u5927\u81f4\u5305\u62ec `2s3z`\u3001`3s5z`\u3001`5m6m`\u3001`3s5z_vs_3s6z`\u3001`2s_vs_1sc`\u3001`6h_vs_8z`\u3001`10m_vs_11m`\u3001`MMM2`\u3001`27m_vs_30m`\u3001`corridor` \u7b49\uff08\u5177\u4f53\u6e05\u5355\u9700\u5728\u4ed3\u5e93\u4e2d grep \u6838\u5b9e\uff09\u3002\n- \u5173\u952e\u73af\u5883\u53c2\u6570\uff1a`map_name`\u3001`sight_range`\u3001`shoot_range`\u3001`state_last_seen`\u3001`return_agent_actions`\uff08SMAX \u76f8\u5bf9 SMAC \u7b80\u5316\u4e86\u90e8\u5206\u7279\u5f81\uff0c\u4f8b\u5982\u89c6\u91ce/\u6b65\u6570\u4ee3\u4ef7\u7684\u5904\u7406\uff09\u3002\n- \u89c2\u6d4b\u4e3a\u5168\u5c40\uff08\u975e\u5c40\u90e8\uff09\u5411\u91cf\u89c2\u6d4b\uff0c\u52a8\u4f5c\u7a7a\u95f4\u4e3a\u79bb\u6563\uff08\u79fb\u52a86 + \u653b\u51fb\u76ee\u6807\u6570 + \u505c\u6b62\uff09\uff0c\u8fd9\u662f SMAX \u4e0e\u539f\u7248 SMAC \u7684\u5173\u952e\u5dee\u5f02\uff0c\u5bf9 QMIX \u7c7b\u65b9\u6cd5\u7684\u5b9e\u73b0\u7ec6\u8282\u6709\u5f71\u54cd\u3002\n\n**\u7b97\u6cd5\u5b9e\u73b0\uff08baselines \u76ee\u5f55\uff09**\n- PPO\uff1a`baselines/IPPO/ippo_ff_smax.py`\uff08\u524d\u9988\uff09\u4e0e `baselines/IPPO/ippo_rnn_smax.py`\uff08\u5faa\u73af\uff09\uff0c\u914d\u5957 `baselines/IPPO/config/` \u4e0b hydra \u914d\u7f6e\uff1b\u53ef\u80fd\u8fd8\u6709 `baselines/MAPPO/`\uff08\u4e2d\u592e\u5316 critic\uff09\u3002\n- Value-based\uff08\"Q-Learning \u7c7b\"\uff09\uff1a`baselines/QMIX/qmix_smax.py`\u3001`baselines/VDN/vdn_smax.py`\uff08DQN \u5f0f\u8bad\u7ec3 + mixing network / \u7ebf\u6027\u6df7\u5408\uff09\uff0c\u53ef\u80fd\u53e6\u6709 `IQL`\u3002**\u6ce8\u610f\uff1aJaxMARL \u4e2d\u6ca1\u6709\u72ec\u7acb\u7684 IDQN baseline\uff08\u9700\u6838\u5b9e\uff09**\uff0cQMIX/VDN \u5373 \u03b5-greedy + TD \u76ee\u6807\u7684 value-based \u65b9\u6cd5\uff0c\u662f\"Q-Learning\"\u6700\u63a5\u8fd1\u7684\u5bf9\u5e94\u7269\u3002\n- \u5173\u952e\u8d85\u53c2\u6570\uff08\u5f85\u4ee5\u4ed3\u5e93\u9ed8\u8ba4\u503c\u4e3a\u51c6\uff09\uff1a\n  - IPPO\uff1a`num_envs`\u3001`num_steps`\u3001`num_minibatches`\u3001`update_epochs`\u3001`lr`\u3001`gamma`\u3001`clip_eps`\u3001`ent_coef`\u3001`vf_coef`\u3001`total_timesteps`\u3001`num_seeds`\u3002\n  - QMIX/VDN\uff1a`buffer_size`\u3001`batch_size`\uff08batch_size_seqs \u00d7 seq_len\uff09\u3001`lr`\u3001`gamma`\u3001`epsilon` \u8c03\u5ea6\u3001`mix_net` \u7ed3\u6784\u3001`target_update`\u3001`total_timesteps`\u3002\n- \u8bc4\u4f30\u6307\u6807\uff1abaselines \u7684 `evaluate` \u51fd\u6570\u5728\u8bad\u7ec3\u4e2d\u5468\u671f\u6027 rollout\uff0c\u8f93\u51fa `return` \u4e0e `win`\uff08battle_won\uff09\uff0c\u6c47\u62a5 **win rate** \u4e0e **average return**\u3002SMAC \u98ce\u683c\u7684 **normalized score**\uff08\u6309\u6bcf\u5f20\u5730\u56fe\u7684 min/max return \u5f52\u4e00\u5316\uff09**\u5f88\u53ef\u80fd\u9700\u8981\u81ea\u884c\u5b9e\u73b0**\u2014\u2014JaxMARL \u5185\u7f6e\u7684\u53ef\u80fd\u662f win rate + raw return\uff0c\u8fd9\u662f\u8bbe\u8ba1\u4e2d\u7684\u4e00\u4e2a\u4e0d\u786e\u5b9a\u70b9\u3002\n\n**\u8bad\u7ec3\u811a\u672c**\uff1a`baselines/*/..._smax.py` \u4ee5 hydra \u547d\u4ee4\u884c\u8fd0\u884c\uff0c\u5982 `python baselines/QMIX/qmix_smax.py algo=... env_name=... total_timesteps=... num_seeds=...`\uff0c\u65e5\u5fd7\u8f93\u51fa\u81f3 wandb/\u672c\u5730\uff08\u9700\u786e\u8ba4\u53ef\u5173\u95ed wandb\uff09\u3002\n\n### (3) \u521d\u6b65\u5b9e\u9a8c\u8bbe\u8ba1\u65b9\u6848\uff08\u603b\u4f53\u601d\u8def\uff09\n\n**\u95ee\u9898**\uff1a\u5728 SMAX \u4e0a\uff0cPPO\uff08IPPO\uff09\u4e0e Q-Learning \u7c7b\u65b9\u6cd5\uff08QMIX\uff0c\u8f85\u4ee5 VDN\uff09\u5728\u8bad\u7ec3\u65f6\u95f4\u548c\u5f52\u4e00\u5316\u5f97\u5206\u4e0a\u7684\u5bf9\u6bd4\u3002\n\n1. **\u73af\u5883\u4e0e\u5730\u56fe\u9009\u62e9**\uff1a\u4ece\u5185\u7f6e\u5730\u56fe\u4e2d\u9009 4\u20136 \u5f20\uff0c\u8986\u76d6\u96be\u5ea6\u68af\u5ea6\uff0c\u4f8b\u5982\u7b80\u5355\uff1a`2s3z`\u3001`5m6m`\uff1b\u4e2d\u7b49\uff1a`3s5z`\u3001`10m_vs_11m`\uff1b\u56f0\u96be\uff1a`3s5z_vs_3s6z`\u3001`6h_vs_8z` \u6216 `MMM2`/`corridor`\uff08\u4ee5\u4ed3\u5e93\u5b9e\u9645\u652f\u6301\u6e05\u5355\u4e3a\u51c6\uff09\u3002\n2. **\u7b97\u6cd5\u5bf9\u7167**\uff1aIPPO\uff08FF \u4e0e RNN \u4e24\u7248\u5404\u8dd1\uff0c\u6216\u9009\u5b9a RNN \u7248\u4e3a\u4e3b\uff09vs QMIX\uff08\u4e3b\u5bf9\u6bd4\uff09\uff0cVDN \u4f5c\u4e3a value-based \u7684\u7b2c\u4e8c\u53c2\u7167\u3002\u5168\u90e8\u4f7f\u7528**\u4ed3\u5e93\u9ed8\u8ba4\u8d85\u53c2\u6570**\uff08\u5373 JaxMARL \u8bba\u6587/\u914d\u7f6e\u6587\u4ef6\u4e2d\u7684\u5b98\u65b9\u8bbe\u7f6e\uff09\uff0c\u4fdd\u8bc1\u4e0e\u5e93\u4f5c\u8005\u610f\u56fe\u4e00\u81f4\uff1b\u8c03\u4f18\u4f5c\u4e3a\u53ef\u9009\u6269\u5c55\u3002\n3. **\u4e24\u79cd\u65f6\u95f4\u5c3a\u5ea6\u540c\u65f6\u5bf9\u6bd4**\uff1a\n   - **\u73af\u5883\u6b65\u6570\u8f74**\uff1a\u7ed9\u6240\u6709\u7b97\u6cd5\u76f8\u540c\u7684 `total_timesteps` \u9884\u7b97\uff08\u5982\u6bcf\u5f20\u5730\u56fe 1\u201310M \u6b65\uff0c\u4f9d\u5730\u56fe\u96be\u5ea6\u8c03\u6574\uff09\uff0c\u753b normalized score vs. env steps \u7684\u5b66\u4e60\u66f2\u7ebf\u2014\u2014\u8861\u91cf\u6837\u672c\u6548\u7387\u3002\n   - **wall-clock \u8f74**\uff1a\u5728**\u540c\u4e00\u786c\u4ef6\u3001\u540c\u4e00 JAX \u7248\u672c\u3001\u56fa\u5b9a\u7ebf\u7a0b\u6570**\u4e0b\u8fd0\u884c\uff0c\u8bb0\u5f55\u6bcf\u8fbe\u5230\u56fa\u5b9a env-step \u68c0\u67e5\u70b9\uff08\u5982\u6bcf 100k \u6b65\uff09\u7684 wall-clock \u65f6\u95f4\uff0c\u753b normalized score vs. wall-clock\u2014\u2014\u8861\u91cf\u5b9e\u9645\u8bad\u7ec3\u901f\u5ea6\u3002\u6d4b\u91cf\u65f6\u7528 `block_until_ready()` \u540c\u6b65\u4ee5\u907f\u514d JAX \u5f02\u6b65\u8ba1\u65f6\u8bef\u5dee\u3002\n4. **\u5f52\u4e00\u5316\u5f97\u5206**\uff1a\u4e3b\u6307\u6807\u4e3a win rate\uff1bnormalized score \u6309\u7ecf\u5178 SMAC \u53e3\u5f84 `(return \u2212 min_return) / (max_return \u2212 min_return)` \u8ba1\u7b97\uff0cmin/max \u7528\u56fa\u5b9a\u53c2\u8003\uff08\u4ed3\u5e93\u63d0\u4f9b\u5219\u7528\u4ed3\u5e93\u503c\uff0c\u5426\u5219\u7528\u8f83\u5f3a\u57fa\u7ebf/\u4e13\u5bb6\u9608\u503c\u5e76\u5728\u8bbe\u8ba1\u4e2d\u56fa\u5b9a\u4e0b\u6765\uff09\u3002\n5. **\u91cd\u590d\u4e0e\u7edf\u8ba1**\uff1a\u6bcf\u4e2a (\u7b97\u6cd5, \u5730\u56fe) \u7ec4\u5408\u81f3\u5c11 3\u20135 \u4e2a\u968f\u673a\u79cd\u5b50\uff08\u5982 0\u20134\uff09\uff0c\u62a5\u544a mean \u00b1 95% CI\uff1b\u8de8\u5730\u56fe\u805a\u5408\u65f6\u6309 SMAC \u60ef\u4f8b\u53d6\u5404\u5730\u56fe\u5f52\u4e00\u5316\u5f97\u5206\u7684**\u4e2d\u4f4d\u6570**\uff0c\u5e76\u7ed9\u51fa\u6700\u7ec8\u68c0\u67e5\u70b9\u7684\u5206\u5e03\u56fe\uff08\u5982 IQM/rliable \u98ce\u683c\uff09\u3002\n6. **\u63a7\u5236\u53d8\u91cf**\uff1a\u76f8\u540c\u7684 SMAX \u73af\u5883\u914d\u7f6e\u3001\u76f8\u540c\u7684\u8bc4\u4f30\u9891\u7387\u4e0e\u8bc4\u4f30 rollout \u6570\u3001\u76f8\u540c\u7684\u603b env-step \u9884\u7b97\u4e0e\u68c0\u67e5\u70b9\u5e8f\u5217\uff1b\u8bb0\u5f55 GPU \u578b\u53f7/JAX/jaxlib \u7248\u672c/SEED\u3002\n7. **\u53ef\u884c\u6027\u5192\u70df\u6d4b\u8bd5\uff08\u771f\u5b9e\u5b9e\u9a8c\u524d\u7684\u68c0\u67e5\uff0c\u4e0d\u5c5e\u672c\u8bbe\u8ba1\u4efb\u52a1\uff09**\uff1a\u5404\u7b97\u6cd5\u5728 `2s3z` \u4e0a\u8dd1 ~10 \u4e07\u6b65\u7684\u77ed\u7a0b\u8fd0\u884c\uff0c\u786e\u8ba4\u811a\u672c\u53ef\u8fd0\u884c\u3001\u65e5\u5fd7\u5b57\u6bb5\u9f50\u5168\u3001\u5355\u6b65\u8017\u65f6\u91cf\u7ea7\uff0c\u4ece\u800c\u6821\u51c6\u603b\u65f6\u95f4\u9884\u7b97\u3002\n\n### (4) \u5173\u952e\u5047\u8bbe\u4e0e\u4e0d\u786e\u5b9a\u4e4b\u5904\n\n**\u5047\u8bbe\uff08\u6211\u65b9\u8bbe\u5b9a\uff0c\u975e\u4efb\u52a1\u786c\u6027\u8981\u6c42\uff09**\n1. \u4f7f\u7528\u4ed3\u5e93\u9ed8\u8ba4\u8d85\u53c2\u6570\u5373\u89c6\u4e3a\"\u516c\u5e73\"\uff08\u8fd9\u662f JaxMARL \u8bba\u6587\u7684\u5bf9\u6bd4\u65b9\u5f0f\uff09\uff1b\u5982\u9700 tuned-vs-tuned \u5bf9\u6bd4\u5219\u6210\u672c\u5927\u5e45\u4e0a\u5347\u3002\n2. \u5355\u5f20 GPU\uff08\u5982 A100\uff09+ \u56fa\u5b9a\u8f6f\u4ef6\u6808\uff08JAX \u7248\u672c pinned\uff09\u4e3a wall-clock \u6bd4\u8f83\u7684\u786c\u4ef6\u57fa\u51c6\u3002\n3. \u6bcf\u7ec4\u5408 5 \u4e2a\u79cd\u5b50\u3001\u6bcf\u5f20\u5730\u56fe\u9884\u7b97\u7ea6 0.5\u20132 \u5c0f\u65f6\u5185\u53ef\u5b8c\u6210\uff08JAX \u52a0\u901f\u4e0b SMAX \u8bad\u7ec3\u5f88\u5feb\uff09\uff0c\u603b\u9884\u7b97\u4f30\u8ba1\u4e3a \u6570\u7ec4\u7b97\u6cd5 \u00d7 ~6 \u5730\u56fe \u00d7 5 \u79cd\u5b50 \u2248 60 \u6b21\u8fd0\u884c\uff0c\u9700 researcher \u786e\u8ba4\u53ef\u63a5\u53d7\u7684\u603b\u65f6\u957f/\u7b97\u529b\u3002\n4. \u4ee5 win rate + SMAC \u5f0f normalized return \u4e3a\u4e3b\u8981\u5f97\u5206\u53e3\u5f84\u3002\n\n**\u4e0d\u786e\u5b9a\u4e4b\u5904**\n1. **\"Q-Learning\" \u7684\u5177\u4f53\u5bf9\u5e94\u5b9e\u73b0**\uff1a\u672c\u73af\u5883\u4e2d\u65e0\u6cd5\u6838\u5b9e\u4ed3\u5e93\u7248\u672c\u91cc\u53ef\u7528\u7684 value-based baseline \u6e05\u5355\uff08QMIX/VDN/IQL \u662f\u5426\u90fd\u5728\u3001\u662f\u5426\u652f\u6301\u5168\u90e8 SMAX \u5730\u56fe\uff09\u3002\u8fd9\u662f\u9700\u8981 researcher \u6216\u540e\u7eed\u4ed3\u5e93\u68c0\u67e5\u786e\u8ba4\u7684\u9996\u8981\u95ee\u9898\u3002\n2. **normalized score \u662f\u5426\u5185\u7f6e**\uff1aJaxMARL \u7684\u8bc4\u4f30\u51fd\u6570\u5f88\u53ef\u80fd\u53ea\u8f93\u51fa win rate \u4e0e raw return\uff0cmin/max \u5f52\u4e00\u5316\u53c2\u7167\u503c\u9700\u8981\u5916\u90e8\u5b9a\u4e49\uff1b\u82e5\u65e0\u5b98\u65b9\u503c\uff0c\u5f52\u4e00\u5316\u53e3\u5f84\u5b58\u5728\u81ea\u7531\u5ea6\u3002\n3. **wall-clock \u516c\u5e73\u6027\u57fa\u51c6**\uff1aPPO\uff08on-policy\u3001\u5927 batch \u5e76\u884c rollout\uff09\u4e0e QMIX\uff08replay buffer\u3001TD \u5b66\u4e60\uff09\u5728 JAX \u4e2d\u7684\u7f16\u8bd1/\u6267\u884c\u7279\u6027\u5dee\u5f02\u5f88\u5927\uff1b\"\u6bcf env \u6b65\u7684 wall-clock\"\u662f\u5426\u662f\u516c\u5e73\u6307\u6807\u3001\u662f\u5426\u5e94\u540c\u65f6\u62a5\u544a\"\u6bcf\u66f4\u65b0\u6b65\u65f6\u95f4\"\u4e0e\u7aef\u5230\u7aef\u603b\u65f6\u95f4\uff0c\u9700\u5728\u6b63\u5f0f\u8bbe\u8ba1\u4e2d\u660e\u786e\u5e76\u53ef\u80fd\u9700\u8981 researcher \u88c1\u51b3\u3002\n4. **\u5730\u56fe\u652f\u6301\u4e0e\u53ef\u7528\u6027**\uff1a\u4e0a\u8ff0\u5730\u56fe\u5217\u8868\u6765\u81ea\u8bb0\u5fc6\uff0c`corridor`/`6h_vs_8z` \u7b49\u5927\u5730\u56fe\u662f\u5426\u5728 SMAX \u4e2d\u53ef\u7528\u3001\u4ee5\u53ca\u5927\u5730\u56fe\u5bf9 QMIX \u5185\u5b58\uff08replay buffer \u7684 JAX \u6570\u7ec4\u5927\u5c0f\uff09\u7684\u538b\u529b\uff0c\u9700\u5728\u4ed3\u5e93\u4e2d\u6838\u5b9e\u3002\n5. **\u79cd\u5b50\u6570\u4e0e\u91cd\u590d\u6b21\u6570\u7684\u4f9d\u636e**\uff1a3\u20135 \u4e2a\u79cd\u5b50\u662f MARL \u6587\u732e\u5e38\u89c4\uff0c\u4f46 SMAX \u4e0a\u7b97\u6cd5\u95f4\u5dee\u5f02\u7684\u65b9\u5dee\u5927\u5c0f\u672a\u77e5\uff0c\u6700\u7ec8\u79cd\u5b50\u6570\u5e94\u4f9d\u636e\u5192\u70df\u6d4b\u8bd5\u7684\u65b9\u5dee\u4f30\u8ba1\u786e\u5b9a\u3002\n6. **RNN vs FF \u7684 PPO \